            "reason": "段落包含大量可沉淀的题材知识，如经济数据、基础设施升级、社会文化影响、场馆建设原则、志愿者规模、火炬传递特色等，这些信息具有长期参考价值，且无明显事件性内容干扰。",
            "knowledge_spans": [
                {
                    "text": "2024年成都体育产业总规模达1306亿元（同比增长12%），2025年预计突破1500亿元；体育消费规模2024年超750亿元，2025年目标800亿元。",
                    "role": "体育产业经济数据",
                    "stability": "high"
                },
                {
                    "text": "优化交通网络（如成洛简快速路）、新增77个体育公园及407个社区运动角。",
                    "role": "基础设施升级措施",
                    "stability": "high"
                },
                {
                    "text": "成都再次向全球展示“公园城市”生态理念与高效办赛能力，获国际世界运动会协会主席多次赞誉。",
                    "role": "国际形象塑造策略",
                    "stability": "medium"
                },
                {
                    "text": "通过“世运新十二月市”等活动，2024年举办全民健身活动超1.1万场，参与人次达4000万。",
                    "role": "全民健身活动规模",
                    "stability": "high"
                },
                {
                    "text": "赛事期间策划“运动员之夜”、非遗技艺体验（蜀绣、皮影戏）等，促进中外文化交流。",
                    "role": "文化输出活动设计",
                    "stability": "medium"
                },
                {
                    "text": "27个竞赛场馆中，18个为既有场馆改造（如高校体育馆），9个依托公园湖泊临时搭建（如兴隆湖湿地公园的铁人两项赛场），无一新建，赛后可快速复原。",
                    "role": "场馆建设节俭原则",
                    "stability": "high"
                },
                {
                    "text": "坚持“能借不租、能租不买”，减少采购成本，赛后器材用于全民健身和青少年训练。",
                    "role": "器材配置策略",
                    "stability": "high"
                },
                {
                    "text": "招募近万名大学生志愿者，设立500余个城市服务站点，提供多语种服务。",
                    "role": "志愿者规模与服务网络",
                    "stability": "high"
                },
                {
                    "text": "史上首次世运会火炬传递于7月26日（今日）启动，途经三星堆、武侯祠等文化地标，120名火炬手包含基层劳动者代表。",
                    "role": "火炬传递特色与路线",
                    "stability": "medium"
                },
                {
                    "text": "在社区设立30个体验点，结合AR/VR技术展示项目知识。",
                    "role": "科技融合推广方式",
                    "stability": "medium"
                }
            ],
